CREATE SEQUENCE IF NOT EXISTS Phs_LogId_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Phs_Log       				                  -- سجل العمليات
( Id          BIGINT NOT NULL,			              -- مفتاح رئيسي
  vType       VARCHAR(50),			                -- النوع
  vText       VARCHAR(1024),				            -- النص
  vUser       VARCHAR(100),				              -- المستخدم
  vIP         VARCHAR(20),				              -- العنوان
  vHost       VARCHAR(64),				              -- الموقع
  vPort       VARCHAR(6),				                -- البوابة
  vRem        VARCHAR(250),			                -- ملاحظات
  dDate       TIMESTAMP Default LOCALTIMESTAMP,                   -- التاريخ والوقت
  CONSTRAINT PhsLog_PK     PRIMARY KEY (Id)
);

-- REVIEW(port): trigger translated mechanically; verify before use.

CREATE OR REPLACE FUNCTION TBID_Phs_Log_fn() RETURNS TRIGGER AS $$
Declare
Begin
  If NEW.Id IS NULL Then
    Select nextval('Phs_LogId_Seq')
      Into NEW.Id;
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS TBID_Phs_Log ON Phs_Log;
CREATE TRIGGER TBID_Phs_Log
  BEFORE INSERT
  ON Phs_Log
  FOR EACH ROW
  EXECUTE FUNCTION TBID_Phs_Log_fn();

