CREATE SEQUENCE IF NOT EXISTS Phs_Audit_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Phs_Audit       				                -- سجل العمليات
( Id          BIGINT NOT NULL,			              -- مفتاح رئيسي
  nType       SMALLINT Default 1,			              -- النوع 1=إضافة, 2=تعديل, 3=حذف
  vTable      VARCHAR(50),				              -- الجدول
  User_Id     BIGINT Default 0,                    -- المستخدم
